        self.gen, self.dv, self.da = gen, np.asarray(v0, float) - v, np.asarray(a0, float) - a
        self.Tv = max(float(Tb), 1e-3)
        self.Ta = accel_window(self.da, self.Tv, dev)

    def step(self, t: float):
        T, v = self.gen.step(t)
        c, dc = blend_offset(t, self.dv, self.da, self.Tv, self.Ta)
        if not np.any(c):
            return T, v
        out = T.copy()
        out[:3, 3] += c[:3]
        out[:3, :3] = matrix_from_rotvec(c[3:]) @ T[:3, :3]
        return out, v + dc


class JointSpline:
    """Timed joint path through points at times (s from the start), from the current reference q0 and its velocity
    dq0 (so a path that replaces a moving one continues smoothly). Cubic Hermite; velocities at the points are given
    or estimated (Catmull-Rom), zero at the end unless given."""

    def __init__(self, q0, points, times, velocities=None, dq0=None):
        P = np.vstack([np.asarray(q0, float)[None], np.asarray(points, float)])
        Tm = np.concatenate([[0.0], np.asarray(times, float)])
        if np.any(np.diff(Tm) <= 0):
            raise ValueError("times must be increasing and positive")
        if velocities is not None:
            V = np.vstack([np.zeros((1, P.shape[1])), np.asarray(velocities, float).reshape(len(P) - 1, -1)])
        else:
            V = np.zeros_like(P)
            for i in range(1, len(P) - 1):
                V[i] = (P[i + 1] - P[i - 1]) / (Tm[i + 1] - Tm[i - 1])
        if dq0 is not None:
            V[0] = np.asarray(dq0, float)
        self.P, self.T, self.V = P, Tm, V
        self.done, self.progress = False, 0.0

    def step(self, t: float):
        Tm, P, V = self.T, self.P, self.V
        if t >= Tm[-1]:
            self.done, self.progress = True, 1.0
            return P[-1].copy(), np.zeros(P.shape[1])
        i = int(np.searchsorted(Tm, t, side="right") - 1)
        h = Tm[i + 1] - Tm[i]
        s = (t - Tm[i]) / h
        h00, h10, h01, h11 = 2 * s**3 - 3 * s**2 + 1, s**3 - 2 * s**2 + s, -2 * s**3 + 3 * s**2, s**3 - s**2
        d00, d10, d01, d11 = 6 * s**2 - 6 * s, 3 * s**2 - 4 * s + 1, -6 * s**2 + 6 * s, 3 * s**2 - 2 * s
        q = h00 * P[i] + h10 * h * V[i] + h01 * P[i + 1] + h11 * h * V[i + 1]
        dq = (d00 * P[i] + d10 * h * V[i] + d01 * P[i + 1] + d11 * h * V[i + 1]) / h
        self.progress = t / Tm[-1]
        return q, dq


class PosePath:
    """A timed pose path for one arm's controlled point: positions by cubic Hermite, rotations by slerp per segment.
    The first pose is the controlled point's pose when the command starts, moving at v0 (m/s, world). velocities:
    the point's linear velocity at each pose (default: Catmull-Rom estimates, zero at the end)."""

    def __init__(self, T0, poses, times, velocities=None, v0=None):
        Ts = [np.asarray(T0, float)] + [np.asarray(T, float) for T in poses]
        tm = np.concatenate([[0.0], np.asarray(times, float)])
        if np.any(np.diff(tm) <= 0):
            raise ValueError("times must be increasing and positive")
        self.T_end = Ts[-1]
        self.pos = JointSpline(Ts[0][:3, 3], [T[:3, 3] for T in Ts[1:]], tm[1:], velocities, v0)
        self.slerp = _Slerp(tm, Ts)
        self.tm = tm
        self.done, self.progress = False, 0.0

    def step(self, t: float):
        tc = min(max(t, 0.0), self.tm[-1])
        p, v = self.pos.step(tc)
        T = np.eye(4)
        T[:3, :3] = self.slerp(tc)
        T[:3, 3] = p
        self.progress = tc / self.tm[-1]
        self.done = t >= self.tm[-1]
        return T, np.concatenate([v, np.zeros(3)])


class PoseLine:
    """Straight line (position) with slerped rotation from T0 to T1 in `duration` s, quintic time scaling."""

    def __init__(self, T0, T1, duration):
        self.T0, self.T1, self.dur = np.asarray(T0, float), np.asarray(T1, float), max(float(duration), 1e-3)
        self.slerp = _Slerp([0.0, 1.0], [self.T0, self.T1])
        self.done, self.progress = False, 0.0

    def step(self, t: float):
        s, ds = _quintic(t / self.dur)
        T = np.eye(4)
        T[:3, :3] = self.slerp(s)
        T[:3, 3] = self.T0[:3, 3] + s * (self.T1[:3, 3] - self.T0[:3, 3])
        v = ds / self.dur * (self.T1[:3, 3] - self.T0[:3, 3])
        self.progress = min(1.0, t / self.dur)
        self.done = t >= self.dur
        return T, np.concatenate([v, np.zeros(3)])


class TwistRef:
    """Constant twist (world frame, m/s and rad/s) for one arm's controlled point, until a duration or a travel limit
    (then done with reason 'max_travel'/'duration'; travel_reason names a travel limit set by something else, e.g.
    'fence'). It ramps from the point's current twist v0 to the target at `accel` (m/s^2; turning at
    ANGULAR_PER_LINEAR times that in rad/s^2), so a re-sent one continues."""
    ANGULAR_PER_LINEAR = 8.0

    def __init__(self, T0, twist, accel, dt, max_travel=None, duration=None, v0=None, travel_reason="max_travel"):
        self.T = np.asarray(T0, float).copy()
        self.p0 = self.T[:3, 3].copy()
        self.tw = np.asarray(twist, float)
        self.accel, self.dt = float(accel), dt
        self.max_travel, self.duration = max_travel, duration
        self.travel_reason = travel_reason
        self.v = np.zeros(6) if v0 is None else np.asarray(v0, float).copy()
        self.done, self.progress, self.reason = False, 0.0, None

    def step(self, t: float):
        if self.done:
            return self.T, np.zeros(6)
        for sl, a in ((slice(0, 3), self.accel), (slice(3, 6), self.accel * self.ANGULAR_PER_LINEAR)):
            d = self.tw[sl] - self.v[sl]
            n = np.linalg.norm(d)
            self.v[sl] += d if n <= a * self.dt else d * (a * self.dt / n)
        v = self.v.copy()
        self.T[:3, 3] = self.T[:3, 3] + v[:3] * self.dt
        if np.linalg.norm(v[3:]) > 0:
            self.T[:3, :3] = matrix_from_rotvec(v[3:] * self.dt) @ self.T[:3, :3]
        travel = np.linalg.norm(self.T[:3, 3] - self.p0)
        if self.max_travel is not None and travel >= self.max_travel:
            self.done, self.reason = True, self.travel_reason
        if self.duration is not None and t >= self.duration:
            self.done, self.reason = True, "duration"
        if self.max_travel:
            self.progress = min(1.0, travel / self.max_travel)
        return self.T, v


class JointVelocityRef:
    """Joint velocities (rad/s), ramped from the current ones dq0 at `accel` (rad/s^2, along a straight line in
    velocity space), until a joint limit or a duration."""

    def __init__(self, q0, vel, accel, dt, lo, hi, duration=None, dq0=None):
        self.q = np.asarray(q0, float).copy()
        self.vel = np.asarray(vel, float)
        self.accel, self.dt, self.lo, self.hi, self.duration = float(accel), dt, lo, hi, duration
        self.dq = np.zeros_like(self.q) if dq0 is None else np.asarray(dq0, float).copy()
        self.done, self.progress, self.reason = False, 0.0, None

    def step(self, t: float):
        if self.done:
            return self.q, np.zeros_like(self.q)
        d = self.vel - self.dq
        n = np.abs(d).max()
        self.dq = self.dq + (d if n <= self.accel * self.dt else d * (self.accel * self.dt / n))
        dq = self.dq.copy()
        q = np.clip(self.q + dq * self.dt, self.lo, self.hi)
        if np.any((q <= self.lo + 1e-9) & (dq < 0)) or np.any((q >= self.hi - 1e-9) & (dq > 0)):
            self.done, self.reason = True, "joint_limit"
        self.q = q
        if self.duration is not None and t >= self.duration:
            self.done, self.reason = True, "duration"
        return self.q, dq


class GripperRef:
    """Finger slide to a target at a speed; done 'reached' at the target, or 'stalled' when the jaws stop short on
    something. Once the slide is at the target, jaws that stay still for stall_s end it either way: within
    STALL_GAP of the target they reached it, beyond it they hold something (no gap between the two can hang)."""
    REACHED_GAP = 0.0008             # m per finger: at the target
    STALL_GAP = 0.0015               # m per finger: stopped this far short = closed on something

    def __init__(self, q0, target, speed, dt, stall_s=0.06):
        self.q, self.target = float(q0), float(target)
        self.speed, self.dt = abs(float(speed)), dt
        self.need = max(1, int(stall_s / dt))
        self.still = 0
        self.done, self.progress, self.reason = False, 0.0, None
        self.span = abs(self.target - self.q) + 1e-9

    def step(self, t: float, q_meas: float, dq_meas: float):
        if not self.done:
            step = np.clip(self.target - self.q, -self.speed * self.dt, self.speed * self.dt)
            self.q += step
            gap = abs(self.target - q_meas)
            self.progress = min(1.0, 1 - gap / self.span)
            at_target = abs(self.q - self.target) < 1e-9
            if at_target and gap < self.REACHED_GAP:
                self.done, self.reason = True, "reached"
            elif at_target and abs(dq_meas) < 0.002:
                self.still += 1
                if self.still >= self.need:
                    self.done, self.reason = True, "stalled" if gap > self.STALL_GAP else "reached"
            else:
                self.still = 0
        return self.q

"""Keep the two arms apart. Each arm is a few capsules around its links (segments between body origins, and from the
gripper body to the TCP) and spheres (a wrist camera); the arms' clearance is the smallest distance between one arm's
capsule surfaces and the other's. The controller (desc["separation"]) refuses a command whose goal brings the arms
closer than min_m, stops an arm whose reference would (as the fence stops one at its box), and latches a Fault when
the measured arms are closer than fault_m. Moving apart is always allowed.

The capsule around a gripper is 8 cm in radius (the jaws fully open), so two hands could never work on one small object.
With spec["fine"] (robotd --separation-fine) the capsules stay as a first pass: while they say the arms are clear,
nothing else runs. When they say otherwise, the hands' pairs are measured on the real meshes instead (convex hulls, with
the fingers where the jaw width puts them), against fine["min_m"] (5 mm, say); the arms' links keep their capsules.

The capsules are conservative (radii from the link meshes' 95th percentile to their maximum around each segment), as
collision spheres in MoveIt or cuRobo are: the real surfaces stay further apart than the clearance says. One
kinematics pass and 36 segment pairs: about 30 us a tick.
"""
from __future__ import annotations

import mujoco
import numpy as np

# The YAM station (robotd/robots/yam_station), measured on the cell's model 2026-11-04 (mesh distance to each segment:
# p95 / max): upper arm 5.4 / 7.5 cm, forearm 7.9 / 10.9 (the elbow housing), wrist 6.9 / 7.4 and 6.3 / 6.4, gripper
# to TCP 5.8 cm (7.7 with the jaws open); the wrist camera's mesh within 5.6 cm of its geom's centre.
YAM = {"capsules": {a: [[f"{a}_link2", f"{a}_link3", 0.065], [f"{a}_link3", f"{a}_link4", 0.085],
                        [f"{a}_link4", f"{a}_link5", 0.075], [f"{a}_link5", f"{a}_gripper", 0.065],
                        [f"{a}_gripper", f"site:tcp_{a}", 0.08]] for a in ("left", "right")},
       "spheres": {a: [[f"{a}_camera", 0.06]] for a in ("left", "right")}}
YAM_HAND = {a: [f"{a}_gripper", f"{a}_tip_left", f"{a}_tip_right", f"{a}_camera"] for a in ("left", "right")}
YAM_NEAR = {a: [f"{a}_link3", f"{a}_link4", f"{a}_link5"] for a in ("left", "right")}


def yam_fine(min_m: float) -> dict:
    """spec["fine"] for the YAM station. fingers: each jaw's joint and its mirror (the kinematics do not apply the
    coupling)."""
    return {"min_m": float(min_m), "hand": YAM_HAND, "near": YAM_NEAR,
            "fingers": {a: [f"{a}_joint7", f"{a}_joint8"] for a in ("left", "right")}}


def seg_seg(p1, q1, p2, q2) -> np.ndarray:
    """Distance between segments p1-q1 and p2-q2 (broadcast over leading axes; a segment may be a point). Ericson,
    Real-Time Collision Detection, 5.1.9."""
    d1, d2, r = q1 - p1, q2 - p2, p1 - p2
    a, e = (d1 * d1).sum(-1), (d2 * d2).sum(-1)
    b, c, f = (d1 * d2).sum(-1), (d1 * r).sum(-1), (d2 * r).sum(-1)
    eps = 1e-12
    pa, pe = a <= eps, e <= eps
    safe = lambda x: np.where(np.abs(x) > eps, x, 1.0)
    denom = a * e - b * b
    s = np.where(denom > eps, np.clip((b * f - c * e) / safe(denom), 0.0, 1.0), 0.0)
    t = (b * s + f) / safe(e)
    s = np.where(t < 0, np.clip(-c / safe(a), 0.0, 1.0), np.where(t > 1, np.clip((b - c) / safe(a), 0.0, 1.0), s))
    t = np.clip(t, 0.0, 1.0)
    # degenerate segments: a point against a segment, or two points
    s = np.where(pa, 0.0, np.where(pe, np.clip(-c / safe(a), 0.0, 1.0), s))
    t = np.where(pa & ~pe, np.clip(f / safe(e), 0.0, 1.0), np.where(pe, 0.0, t))
    c1, c2 = p1 + d1 * s[..., None], p2 + d2 * t[..., None]
    return np.linalg.norm(c1 - c2, axis=-1)


class Separation:
    """The two arms' clearance on a MuJoCo model, from spec ({"capsules": {arm: [[A, B, r], ...]}, "spheres": {arm:
    [[BODY, r], ...]}}; A and B are body names or "site:NAME"; a sphere sits at the centre of the body's first geom)."""

    def __init__(self, model: mujoco.MjModel, spec: dict, min_m: float, fault_m: float = 0.0):
        self.m, self.min_m, self.fault_m = model, float(min_m), float(fault_m)
        self.arms = list(spec["capsules"])
        if len(self.arms) != 2:
            raise ValueError(f"separation needs two arms, got {self.arms}")
        ref = lambda name: (("site", model.site(name[5:]).id) if name.startswith("site:")
                            else ("body", model.body(name).id))
        self.caps = {a: [(ref(x), ref(y), float(rad)) for x, y, rad in spec["capsules"][a]] for a in self.arms}
        self.spheres = {a: [(int(np.flatnonzero(model.geom_bodyid == model.body(b).id)[0]), float(rad))
                            for b, rad in (spec.get("spheres") or {}).get(a, [])] for a in self.arms}
        self.names = {a: [f"{x}-{y}" for x, y, _ in spec["capsules"][a]] + [b for b, _ in
                                                                            (spec.get("spheres") or {}).get(a, [])]
                      for a in self.arms}
        self.fine = spec.get("fine")
        if self.fine:
            mesh = lambda b: [g for g in np.flatnonzero(model.geom_bodyid == model.body(b).id)
                              if model.geom_type[g] == mujoco.mjtGeom.mjGEOM_MESH]
            hand = {a: [g for b in self.fine["hand"][a] for g in mesh(b)] for a in self.arms}
            near = {a: [g for b in self.fine["near"][a] for g in mesh(b)] for a in self.arms}
            a, b = self.arms
            self.fine_pairs = [(int(x), int(y)) for x in hand[a] for y in hand[b] + near[b]] + \
                              [(int(x), int(y)) for x in near[a] for y in hand[b]]
            self.fine_shift = self.min_m - float(self.fine["min_m"])
            adr = lambda n: int(model.jnt_qposadr[model.joint(n).id])
            self.mimic = [(adr(x), adr(y)) for x, y in self.fine["fingers"].values()]
            self.hand_shape = {a: np.array([y.startswith("site:") for _, y, _ in spec["capsules"][a]] +
                                           [True] * len((spec.get("spheres") or {}).get(a, []))) for a in self.arms}

    def _shapes(self, d, arm):
        pt = lambda r: d.site_xpos[r[1]] if r[0] == "site" else d.xpos[r[1]]
        P = [pt(x) for x, _, _ in self.caps[arm]] + [d.geom_xpos[g] for g, _ in self.spheres[arm]]
        Q = [pt(y) for _, y, _ in self.caps[arm]] + [d.geom_xpos[g] for g, _ in self.spheres[arm]]
        R = [r for _, _, r in self.caps[arm]] + [r for _, r in self.spheres[arm]]
        return np.array(P), np.array(Q), np.array(R)

    def clearance(self, d) -> tuple:
        """(clearance in m, (left shape, right shape)) for the positions in d (kinematics already run)."""
        (P1, Q1, R1), (P2, Q2, R2) = (self._shapes(d, a) for a in self.arms)
        dist = seg_seg(P1[:, None], Q1[:, None], P2[None], Q2[None]) - R1[:, None] - R2[None]
        i, j = np.unravel_index(int(np.argmin(dist)), dist.shape)
        first = float(dist[i, j]), (self.names[self.arms[0]][i], self.names[self.arms[1]][j])
        if not self.fine or first[0] >= self.min_m:
            return first
        a, b = self.arms                                # the hands' pairs on their meshes, the links' on capsules
        rest = np.where(self.hand_shape[a][:, None] | self.hand_shape[b][None], np.inf, dist)
        i, j = np.unravel_index(int(np.argmin(rest)), rest.shape)
        best = float(rest[i, j]), (self.names[a][i], self.names[b][j])
        fromto = np.zeros(6)
        for x, y in self.fine_pairs:
            gap = mujoco.mj_geomDistance(self.m, d, x, y, 0.2, fromto) + self.fine_shift
            if gap < best[0]:
                best = gap, (self.m.body(self.m.geom_bodyid[x]).name, self.m.body(self.m.geom_bodyid[y]).name)
        return best

    def at(self, kin, q: dict) -> tuple:
        """The clearance with the arms at joint values q ({name: rad}, every arm joint), on kin's own data."""
        kin.set_q(q)
        if self.fine:
            for x, y in self.mimic:
                kin.d.qpos[y] = kin.d.qpos[x]
        mujoco.mj_kinematics(kin.m, kin.d)
        return self.clearance(kin.d)

